<?php use CmuLms\View;$title='Gradebook';include __DIR__.'/../layout/header.php';?><section class="card"><h1>Gradebook</h1><table><tr><th>Course</th><th>Assessment</th><th>Category</th><th>Score</th><th>Released</th></tr><?php foreach($grades as $g):?><tr><td><?=View::e($g['course_code'])?></td><td><?=View::e($g['title'])?></td><td><?=View::e($g['category'])?></td><td><?=View::e($g['score'])?> / <?=View::e($g['max_score'])?></td><td><?=!empty($g['released'])?'Yes':'No'?></td></tr><?php endforeach;?></table></section><?php include __DIR__.'/../layout/footer.php';?>
